-- Open Rec Lite: seed mock talent pool (30 profiles)
on conflict (candidate_id) do update set
  display_name = excluded.display_name, headline = excluded.headline,
  years_experience = excluded.years_experience, seniority = excluded.seniority,
  skills = excluded.skills, timezone_offsets = excluded.timezone_offsets,
  availability = excluded.availability, summary = excluded.summary;
